let replacement:ReturnType<typeof startHub>|undefined;let f:Fixture|undefined;const roots:string[]=[];const bridges:MachineBridge[]=[];const owners:Array<{stop():Promise<void>}>=[];
/** Every bridge notice of a test, shutdown included. The generic fallback means an unclassified failure source, so it fails the test. */
const notices:string[]=[];const recordNotice=(code:string)=>{notices.push(code);console.log('bridge notice',code);};
