async function local(base=tmpdir()){
 f=await fixture();const root=mkdtempSync(path.join(base,'machine-bridge-'));roots.push(root);const cwd=path.join(root,'checkout');Bun.spawnSync(['git','init','-q',cwd]);writeFileSync(path.join(cwd,'seed.txt'),'seed');Bun.spawnSync(['git','-C',cwd,'add','.']);expect(Bun.spawnSync(['git','-C',cwd,'-c','user.name=Fixture','-c','user.email=test@example.invalid','-c','commit.gpgsign=false','-c','core.hooksPath=/dev/null','commit','-qm','fixture']).exitCode).toBe(0);
 const configDir=path.join(root,'config');const hubId=hubIdentity(f.origin);const ledger=new MachineLedger(path.join(machineStateDir(configDir,hubId),'control.sqlite'));
 const pair=await success<{code:string}>(await f.call('/hub/v2/machines/pairings',{method:'POST',cookie:f.cookie,body:{displayName:'Native machine',projectIds:[f.project.id]}}));const machine=await enrollMachine(f.origin,{code:pair.code,agentVersion:'test-native',ledgerId:ledger.ledgerId});ledger.close();saveEnrollment(configDir,{hubUrl:f.origin,...machine});allowCheckout(configDir,{projectId:f.project.id,checkoutId:'checkout',cwd,profileId:'fixture'});
 const policy:Control['LocalMachinePolicy']={version:2,hubId,enabled:true,maxConcurrentRuns:2,checkouts:[{projectId:f.project.id,checkoutId:'checkout',localBindingId:'binding',path:cwd,profileIds:['fixture']}],allowAdHocSessions:true,allowedCandidateIds:['scripted:m'],profiles:[{profileId:'fixture',allowAdHocTurns:true,consentVersion:1,allowedCandidateIds:['scripted:m']}]};
 return {root,cwd,configDir,hubId,machine,policy};
}
// Real processes and sockets under a loaded parallel run can take seconds to settle. Every wait expects success, so the budget is time-based and generous; a passing wait still returns on the first matching read.
setDefaultTimeout(30_000);
async function wait<T>(read:()=>Promise<T>,done:(value:T)=>boolean,attempts=150):Promise<T>{const deadline=Date.now()+Math.max(attempts*10,10_000);for(;;){const value=await read();if(done(value))return value;if(Date.now()>=deadline)throw new Error('bridge observation timeout');await Bun.sleep(10);}}
test('actual authenticated Hub creates a leased native session and publishes measured clean baseline',async()=>{
 const localState=await local();const digest=canonicalDigest(localState.policy);const provider=scriptedProvider([okReply]);const routing:Control['RoutingAvailability']={version:1,policyDigest:digest,capabilityDigest:digest,profileIds:['local'],candidates:[{candidateId:'scripted:m',providerId:'scripted',modelId:'m',reasoningEfforts:['none'],available:true,reason:'none',privacyClass:'local',costClass:'local'}]};
 const bridge=new MachineBridge({onNotice:recordNotice,configDir:localState.configDir,enrollment:loadEnrollment(localState.configDir)!,policy:localState.policy,resolveProfile:async()=>({ok:true,value:{profileId:'fixture',policyDigest:digest,capabilityDigest:digest,catalogue:createCommandCatalogue(digest),routing,createRuntime:async()=>({ok:true,value:createNativeSessionRuntime({cwd:localState.cwd,provider:provider.provider,providerId:'scripted',modelId:'m',availability:routing})})}})});bridges.push(bridge);await bridge.start();
 const inventory=await wait(async()=>success<{inventory:{inventoryVersion:number;checkouts:Array<{headSha:string}>}|null}>(await f!.call(`/hub/v2/machines/${localState.machine.machineId}`,{cookie:f!.cookie})),v=>v.inventory!==null);
 const receipt=await success<Control['SessionOperationReceipt']>(await f!.call(`/hub/v2/projects/${f!.project.id}/sessions`,{method:'POST',cookie:f!.cookie,body:{machineId:localState.machine.machineId,checkoutId:'checkout',agentProfileId:'fixture',expectedInventoryVersion:inventory.inventory!.inventoryVersion,expectedHeadSha:inventory.inventory!.checkouts[0]!.headSha,capabilityDigest:digest,policyDigest:digest,title:'Native network session'}}));
 const record=await wait(async()=>success<Control['SessionRecord']>(await f!.call(`/hub/v2/projects/${f!.project.id}/sessions/${receipt.sessionId}`,{cookie:f!.cookie})),v=>v.state==='idle');const measured=bridge.baseline(receipt.sessionId);if(measured===undefined)throw new Error('missing measured baseline');expect(record.workspaceBaseline).toBe(measured);expect(record.controller).toBeNull();expect(provider.requests).toHaveLength(0);
 expect(bridge.connected).toBe(true); const sessionPath=`/hub/v2/projects/${f!.project.id}/sessions/${record.sessionId}`;
 let claim=await success<Control['ControllerReceipt']>(await f!.call(`${sessionPath}/controller/claim`,{method:'POST',cookie:f!.cookie,body:{expectedSessionVersion:record.version,expectedControllerVersion:0,requestedLeaseSeconds:59,mode:'claim'}}));
 let controlled=await wait(async()=>success<Control['SessionRecord']>(await f!.call(sessionPath,{cookie:f!.cookie})),v=>v.controller?.controllerLeaseId===claim.lease.controllerLeaseId);
 const previousCursor=controlled.sessionEventCursor;
 const renewed=await success<Control['ControllerReceipt']>(await f!.call(`${sessionPath}/controller/renew`,{method:'POST',cookie:f!.cookie,body:{expectedSessionVersion:controlled.version,expectedControllerVersion:claim.lease.version,controllerLeaseId:claim.lease.controllerLeaseId,requestedLeaseSeconds:60,mode:'renew'}}));expect(renewed.lease.version).toBe(claim.lease.version);expect(renewed.lease.controllerLeaseId).toBe(claim.lease.controllerLeaseId);
 controlled=await wait(async()=>success<Control['SessionRecord']>(await f!.call(sessionPath,{cookie:f!.cookie})),v=>v.version===renewed.sessionVersion&&v.sessionEventCursor>=previousCursor+2);expect(controlled.controller!.expiresAt).toBe(renewed.lease.expiresAt);claim=renewed;
 const statusReceipt=await success<Control['CommandOutcome']>(await f!.call(`${sessionPath}/commands/invoke`,{method:'POST',cookie:f!.cookie,body:{expectedSessionVersion:controlled.version,expectedConfigVersion:controlled.config.configVersion,controller:{controllerLeaseId:claim.lease.controllerLeaseId,expectedControllerVersion:claim.lease.version},catalogueDigest:createCommandCatalogue(digest).catalogueDigest,commandName:'status',arguments:{},busyPolicy:'reject'}}));
 const commandResult=await wait(async()=>success<Control['CommandOutcome']>(await f!.call(`${sessionPath}/operations/${statusReceipt.operationId}`,{cookie:f!.cookie})),v=>v.status==='applied');expect(commandResult.commandName).toBe('status');
 const turn=await success<Control['TurnReceipt']>(await f!.call(`${sessionPath}/messages`,{method:'POST',cookie:f!.cookie,key:'native-message-one',body:{expectedSessionVersion:controlled.version,expectedConfigVersion:controlled.config.configVersion,controller:{controllerLeaseId:claim.lease.controllerLeaseId,expectedControllerVersion:claim.lease.version},text:'Reply using actual native provider',interpretation:'literal-message',busyPolicy:'enqueue',association:{mode:'ad-hoc',profileConsentVersion:1}}}));
 expect(turn.status).toBe('admitted');const observed=await wait(async()=>success<{state:string}>(await f!.call(`/hub/v2/projects/${f!.project.id}/runs/${turn.runId}`,{cookie:f!.cookie})),v=>v.state==='succeeded');expect(observed.state).toBe('succeeded');expect(provider.requests).toHaveLength(1);

});

