 const claim=await success<Control['ControllerReceipt']>(await f!.call(`${sessionPath}/controller/claim`,{method:'POST',cookie:f!.cookie,body:{expectedSessionVersion:record.version,expectedControllerVersion:0,requestedLeaseSeconds:59,mode:'claim'}}));
