 const publication=await wait(async()=>success<{result?:Control['ResultReceipt']}>(await f!.call(`/hub/v2/projects/${f!.project.id}/runs/${turn.runId}`,{cookie:f!.cookie})),v=>v.result!==undefined);expect(publication.result!.checksKind).toBe('RunChecks');expect(publication.result!.flowId).toBeNull();expect(publication.result!.evidenceId).toBeNull();

