/** Real Hub, real MachineBridge and the real owner-only Unix socket; a short controller lease expires in real time. */
async function ownerFixture(options:{spawner?:NativeRuntimeOptions['spawner']}={}){
 const localState=await local(process.platform==='darwin'?'/private/tmp':tmpdir());const digest=canonicalDigest(localState.policy);const provider=scriptedProvider([okReply,okReply]);const runtimes:NativeSessionRuntime[]=[];const routing:Control['RoutingAvailability']={version:1,policyDigest:digest,capabilityDigest:digest,profileIds:['local'],candidates:[{candidateId:'scripted:m',providerId:'scripted',modelId:'m',reasoningEfforts:['none'],available:true,reason:'none',privacyClass:'local',costClass:'local'}]};
 const bridge=new MachineBridge({onNotice:recordNotice,configDir:localState.configDir,enrollment:loadEnrollment(localState.configDir)!,policy:localState.policy,resolveProfile:async()=>({ok:true,value:{profileId:'fixture',policyDigest:digest,capabilityDigest:digest,catalogue:createCommandCatalogue(digest),routing,createRuntime:async()=>{const runtime=createNativeSessionRuntime({cwd:localState.cwd,provider:provider.provider,providerId:'scripted',modelId:'m',availability:routing,...(options.spawner?{spawner:options.spawner}:{})});runtimes.push(runtime);return{ok:true,value:runtime};}}})});bridges.push(bridge);await bridge.start();
 const inventory=await wait(async()=>success<{inventory:{inventoryVersion:number;checkouts:Array<{headSha:string}>}|null}>(await f!.call(`/hub/v2/machines/${localState.machine.machineId}`,{cookie:f!.cookie})),v=>v.inventory!==null);
 const created=await success<Control['SessionOperationReceipt']>(await f!.call(`/hub/v2/projects/${f!.project.id}/sessions`,{method:'POST',cookie:f!.cookie,body:{machineId:localState.machine.machineId,checkoutId:'checkout',agentProfileId:'fixture',expectedInventoryVersion:inventory.inventory!.inventoryVersion,expectedHeadSha:inventory.inventory!.checkouts[0]!.headSha,capabilityDigest:digest,policyDigest:digest,title:'Owner recovery session'}}));
 const sessionPath=`/hub/v2/projects/${f!.project.id}/sessions/${created.sessionId}`;const read=async()=>success<Control['SessionRecord']>(await f!.call(sessionPath,{cookie:f!.cookie}));await wait(read,v=>v.state==='idle');
 const owner=await startMachineOwnerControl(localState.configDir,new Map([[localState.hubId,bridge]]));owners.push(owner);
 const ask=(input:unknown)=>requestLocalOwnerControl(localState.configDir,input);let inspections=0;
 const inspect=async():Promise<Inspection>=>{const result=await ask({v:1,requestId:`owner-inspect-${++inspections}`,operation:'inspect',hubId:localState.hubId,sessionId:created.sessionId});if(!result.ok||result.value.kind!=='inspection')throw new Error(result.ok?'unexpected owner value':result.error.code);return result.value;};
 const target=(view:Inspection)=>{const entry=view.sessions[0]!;return{sessionId:entry.session.sessionId,nativeSessionId:entry.nativeSessionId,controllerLeaseId:entry.session.controller!.controllerLeaseId,controllerVersion:entry.session.controller!.version,expectedSessionVersion:entry.session.version,expectedHistoryVersion:entry.session.historyVersion,expectedWorkspaceBaseline:entry.session.workspaceBaseline};};
 const release=(requestId:string,pins:ReturnType<typeof target>)=>ask({v:1,requestId,operation:'release-expired-idle',hubId:localState.hubId,target:pins});
 const code=(result:Awaited<ReturnType<typeof ask>>)=>result.ok?'applied':result.error.code;
 const claim=async(seconds:number)=>{const current=await read();const receipt=await success<Control['ControllerReceipt']>(await f!.call(`${sessionPath}/controller/claim`,{method:'POST',cookie:f!.cookie,body:{expectedSessionVersion:current.version,expectedControllerVersion:current.controller?.version??0,requestedLeaseSeconds:seconds,mode:'claim'}}));await wait(read,v=>v.controller?.controllerLeaseId===receipt.lease.controllerLeaseId);return receipt;};
 const expire=async(lease:Control['ControllerLease'])=>{await Bun.sleep(Math.max(0,Date.parse(lease.expiresAt)-Date.now()+150));};
 return {localState,bridge,provider,runtimes,sessionId:created.sessionId,sessionPath,read,ask,inspect,target,release,code,claim,expire};
}
